pub fn action_type(action: &Action) -> &'static str {
    match action {
        Action::Click { .. } => "click",
        Action::Type { .. } => "type",
        Action::Select { .. } => "select",
        Action::Scroll { .. } => "scroll",
        Action::Wait { .. } => "wait",
        Action::Navigate { .. } => "navigate",
        Action::Back => "back",
        Action::Extract { .. } => "extract",
        Action::Done { .. } => "done",
    }
}

#[derive(Debug)]
pub struct ActionSummary<'a> {
    pub action_type: &'static str,
    pub id: Option<&'a str>,
    pub text_len: Option<usize>,
    pub submit: Option<bool>,
    pub value_len: Option<usize>,
    pub url: Option<&'a str>,
    pub scroll: Option<(i64, i64)>,
    pub wait_ms: Option<u64>,
    pub query_len: Option<usize>,
    pub summary_len: Option<usize>,
}

impl<'a> From<&'a Action> for ActionSummary<'a> {
    fn from(action: &'a Action) -> Self {
        match action {
            Action::Click { id } => ActionSummary {
                action_type: "click",
                id: Some(id.as_str()),
                text_len: None,
                submit: None,
                value_len: None,
                url: None,
                scroll: None,
                wait_ms: None,
                query_len: None,
                summary_len: None,
            },
            Action::Type { id, text, submit } => ActionSummary {
                action_type: "type",
                id: Some(id.as_str()),
                text_len: Some(text.chars().count()),
                submit: *submit,
                value_len: None,
                url: None,
                scroll: None,
                wait_ms: None,
                query_len: None,
                summary_len: None,
            },
            Action::Select { id, value } => ActionSummary {
                action_type: "select",
                id: Some(id.as_str()),
                text_len: None,
                submit: None,
                value_len: Some(value.chars().count()),
                url: None,
                scroll: None,
                wait_ms: None,
                query_len: None,
                summary_len: None,
            },
            Action::Scroll { dx, dy } => ActionSummary {
                action_type: "scroll",
                id: None,
                text_len: None,
                submit: None,
                value_len: None,
                url: None,
                scroll: Some((*dx, *dy)),
                wait_ms: None,
                query_len: None,
                summary_len: None,
            },
            Action::Wait { ms } => ActionSummary {
                action_type: "wait",
                id: None,
                text_len: None,
                submit: None,
                value_len: None,
                url: None,
                scroll: None,
                wait_ms: Some(*ms),
                query_len: None,
                summary_len: None,
            },
            Action::Navigate { url } => ActionSummary {
                action_type: "navigate",
                id: None,
                text_len: None,
                submit: None,
                value_len: None,
                url: Some(url.as_str()),
                scroll: None,
                wait_ms: None,
                query_len: None,
                summary_len: None,
            },
            Action::Back => ActionSummary {
                action_type: "back",
                id: None,
                text_len: None,
                submit: None,
                value_len: None,
                url: None,
                scroll: None,
                wait_ms: None,
                query_len: None,
                summary_len: None,
            },
            Action::Extract { query, id } => ActionSummary {
                action_type: "extract",
                id: id.as_deref(),
                text_len: None,
                submit: None,
                value_len: None,
                url: None,
                scroll: None,
                wait_ms: None,
                query_len: Some(query.chars().count()),
                summary_len: None,
            },
            Action::Done { summary } => ActionSummary {
                action_type: "done",
                id: None,
                text_len: None,
                submit: None,
                value_len: None,
                url: None,
                scroll: None,
                wait_ms: None,
                query_len: None,
                summary_len: Some(summary.chars().count()),
            },
        }
    }
}

pub fn init_tracing() {
    use tracing_subscriber::filter::EnvFilter;
    use tracing_subscriber::fmt;

    let filter = EnvFilter::try_from_default_env()
        .unwrap_or_else(|_| EnvFilter::new("info"));
    let _ = fmt()
        .with_env_filter(filter)
        .with_writer(std::io::stderr)
        .json()
        .try_init();
}

