        assert_eq!(snapshot.actions_click_total, 1);
        assert_eq!(snapshot.last_llm_duration_ms, 12);
        assert_eq!(snapshot.last_step_duration_ms, 7);
        assert_eq!(snapshot.no_progress_streak, 3);
    }
